import copy
import hashlib
import json
import pathlib
import re
import subprocess

from defusedxml import ElementTree

repo = pathlib.Path('/workspace/e02-E-continuation-20261006')
receipt_path = repo / 'policy-engine/docs/research/e02-cloud-test-plan/implementation-handoffs/E/continuation-20261006/pr38-r3/composed-imports-morris.json'
receipt = json.loads(receipt_path.read_text())

def check(value):
    for key in ('base_sha', 'candidate_sha', 'candidate_tree'):
        if not re.fullmatch('[0-9a-f]{40}', value[key]):
            raise ValueError('Nonliteral source identity')
    def git(*args):
        return subprocess.check_output(['git', '-C', str(repo), *args], text=True).strip()
    if git('rev-parse', value['candidate_sha'] + '^{tree}') != value['candidate_tree']:
        raise ValueError('Tree differs')
    if git('diff', '--name-only', value['base_sha'], value['candidate_sha']).splitlines() != value['complete_changed_paths']:
        raise ValueError('Footprint differs')
    for asset in value['assets']:
        path = (repo / asset['path']).resolve()
        if not path.is_relative_to(repo) or not path.is_file():
            raise ValueError('Asset escapes or missing')
        data = path.read_bytes()
        if len(data) != asset['bytes'] or hashlib.sha256(data).hexdigest() != asset['sha256']:
            raise ValueError('Asset differs')
    cases = ElementTree.parse(receipt_path.parent / 'composed-imports-morris/composed-pytest.xml').findall('.//testcase')
    actual_count = len(cases)
    if any(case.find('failure') is not None or case.find('error') is not None or case.find('skipped') is not None for case in cases):
        raise ValueError('PASS partition differs')
    if value['checks']['composed_affected_consumer']['cases'] != actual_count:
        raise ValueError('JUnit denominator differs')

check(receipt)
controls = [{'control': 'healthy', 'status': 'PASS', 'count_basis': 'Actual bound JUnit testcase records, no hardcoded case count'}]
mutations = [
    ('tree', lambda value: value.__setitem__('candidate_tree', '0' * 40)),
    ('footprint', lambda value: value['complete_changed_paths'].pop()),
    ('size', lambda value: value['assets'][0].__setitem__('bytes', value['assets'][0]['bytes'] + 1)),
    ('hash', lambda value: value['assets'][0].__setitem__('sha256', '0' * 64)),
    ('count', lambda value: value['checks']['composed_affected_consumer'].__setitem__('cases', value['checks']['composed_affected_consumer']['cases'] - 1)),
]
for name, mutate in mutations:
    bad = copy.deepcopy(receipt)
    mutate(bad)
    try:
        check(bad)
    except ValueError as error:
        controls.append({'control': name, 'status': 'FAIL as required', 'reason': str(error)})
    else:
        raise RuntimeError('Corrupt input accepted: ' + name)
print(json.dumps({'source_candidate': receipt['candidate_sha'], 'controls': controls}, indent=2))

